{
  "sections": [
    {
      "key": "verdict",
      "title": "निर्णय",
      "text": "तुमचा दुग्ध प्रकल्प आर्थिकदृष्ट्या व्यवहार्य आहे. सर्व प्रमुख संकेतक जसे की किमान DSCR {{min_dscr}} आणि पेबॅक कालावधी {{payback_months}} महिने योग्य आहेत."
    },
    {
      "key": "market",
      "title": "बाजार स्थिती",
      "text": "या गावात अंदाजे {{households}} घरांपर्यंत ग्राहकसंख्या आहे. सध्या जवळचे स्पर्धक कमी आहेत आणि बाजारातील अंतर कमी आहे, ज्यामुळे तुमचा उत्पादन थेट घरांपर्यंत पोहोचवता येईल."
    },
    {
      "key": "pricing",
      "title": "किंमत निर्धारण",
      "text": "दुग्ध उत्पादनाची किंमत स्थानिक बाजारपेठेच्या सरासरीशी सुसंगत ठेवावी. सबसिडी आणि कर्जाच्या अटींचा विचार करून खर्चात मार्जिन ठेवणे महत्त्वाचे आहे."
    },
    {
      "key": "risks",
      "title": "जोखीमे",
      "text": "मुख्य जोखीमे म्हणजे कच्चा मालाची किंमत बदल, हवामानाचा प्रभाव आणि ग्राहकांच्या मागणीतील अनिश्चितता. तसेच, कर्जाची परतफेड वेळेवर न करता आल्यास आर्थिक दबाव वाढू शकतो."
    },
    {
      "key": "path_to_yes",
      "title": "यशस्वी होण्याचा मार्ग",
      "text": "अभिनंदन! तुमचा प्रकल्प आधीच सर्व आवश्यक निकष पूर्ण करतो. कोणतेही अतिरिक्त बदल आवश्यक नाहीत."
    },
    {
      "key": "next_steps",
      "title": "पुढील पावले",
      "text": "पहिले, PMEGP योजनेखाली कर्ज अर्ज करा (रक्कम {{loan}}). दुसरे, सबसिडी {{subsidy}} मिळविण्यासाठी आवश्यक कागदपत्रे तयार करा. तिसरे, शेतातील पिंजरा {{cost.shed}} आणि बफेलो {{cost.animals}} खरेदी करा. चौथे, कार्यशील भांडवल {{working_capital}} व्यवस्थापित करा. पाचवे, उत्पादन सुरू करा आणि स्थानिक ग्राहकांपर्यंत वितरण चॅनेल स्थापन करा."
    }
  ],
  "swot": {
    "strengths": [
      "उच्च सबसिडी मिळण्याची संधी",
      "कमी स्पर्धा आणि स्थानिक बाजारपेठेची उपलब्धता",
      "PMEGP कर्जाची सोपी उपलब्धता"
    ],
    "weaknesses": [
      "प्रारंभीचे मोठे भांडवल खर्च",
      "कर्ज परतफेडीची जबाबदारी"
    ],
    "opportunities": [
      "स्थानिक ग्राहकांपर्यंत थेट विक्रीचा विस्तार",
      "सहकारी केंद्रांशी भागीदारी"
    ],
    "threats": [
      "कच्चा माल (बफेलो) किंमतीतील चढउतार",
      "हवामान व रोगांमुळे उत्पादनावर परिणाम"
    ]
  }
}
